package cm.naxa.grillad
import androidx.compose.material3.*
import androidx.compose.runtime.*
import kotlinx.coroutines.launch
import org.json.JSONObject
@Composable internal fun GrilladPaymentQuote(data:JSONObject?,enabled:Boolean,request:suspend(JSONObject)->JSONObject){
 val pending=rows(data?.optJSONArray("central_requests")).firstOrNull{it.optString("kind")=="renewal"&&it.optString("status")=="pending"}?:return
 var channel by remember(pending.optString("id")){mutableStateOf("mtn_momo")};var result by remember(pending.optString("id")){mutableStateOf<JSONObject?>(null)};var busy by remember{mutableStateOf(false)};var msg by remember{mutableStateOf("")};var payer by remember{mutableStateOf("")};var reference by remember{mutableStateOf("")};var occurred by remember{mutableStateOf("")};var sms by remember{mutableStateOf("")};val scope=rememberCoroutineScope()
 Text("Référence de paiement",style=MaterialTheme.typography.titleMedium);Text("Abonnement uniquement : règlement externe, preuve de débit et vérification indépendante du crédit. Aucun débit automatique.")
 listOf("mtn_momo" to "MTN MoMo","orange_money" to "Orange Money").forEach{(k,v)->TextButton({channel=k;result=null},enabled=enabled&&!busy){Text((if(channel==k)"✓ " else "")+v)}}
 Button({busy=true;msg="";scope.launch{try{result=request(obj("action" to "payment_quote","request" to pending.optString("id"),"channel" to channel))}catch(e:kotlinx.coroutines.CancellationException){throw e}catch(e:Exception){msg="Référence indisponible. Contactez le centre."}finally{busy=false}}},enabled=enabled&&!busy){Text("Créer la référence de paiement")}
 result?.let{Text("Aucun débit effectué");Text("Référence : "+it.optString("intent")+" · "+it.optString("amount")+" F");Text("Canal enregistré : "+when(it.optString("channel")){"orange_money"->"Orange Money";"bank"->"Banque";else->"MTN MoMo"});if(it.optString("status")=="expired")Text("Référence expirée. Ne versez rien ; contactez le centre.") else if(it.optJSONObject("destination")!=null){val dest=it.getJSONObject("destination");Text("Bénéficiaire : "+dest.optString("beneficiary")+" · "+dest.optString("reference"));OutlinedTextField(sms,{sms=it.take(8000)},label={Text("SMS de débit partagé volontairement")});TextButton({busy=true;scope.launch{try{val c=request(obj("action" to "subscription_sms_candidate","request" to pending.optString("id"),"channel" to it.optString("channel"),"sms" to sms));payer=c.optString("payer");reference=c.optString("reference");if(!c.isNull("occurred"))occurred=java.time.Instant.parse(c.getString("occurred")).atZone(java.time.ZoneId.of("Africa/Douala")).toLocalDateTime().toString();sms="";msg="Champs extraits, déclaration à vérifier."}catch(e:kotlinx.coroutines.CancellationException){throw e}catch(e:Exception){msg="SMS non exploitable. Saisie manuelle."}finally{busy=false}}},enabled=enabled&&!busy&&sms.trim().length>=12){Text("Extraire la référence du SMS")};OutlinedTextField(payer,{payer=it},label={Text("Numéro payeur (9 chiffres)")});OutlinedTextField(reference,{reference=it},label={Text("Référence règlement abonnement")});OutlinedTextField(occurred,{occurred=it},label={Text("Date et heure (AAAA-MM-JJTHH:mm)")});Button({busy=true;scope.launch{try{val date=java.time.LocalDateTime.parse(occurred).atZone(java.time.ZoneId.of("Africa/Douala")).toInstant().toString();request(obj("action" to "subscription_declare","request" to pending.optString("id"),"reference" to reference,"amount" to it.optLong("amount"),"payer" to payer,"occurred" to date));msg="Déclaration enregistrée — vérification indépendante requise."}catch(e:kotlinx.coroutines.CancellationException){throw e}catch(e:Exception){msg="Déclaration non confirmée."}finally{busy=false}}},enabled=enabled&&!busy&&payer.matches(Regex("[0-9]{9}"))&&reference.length>=5){Text("Déclarer le règlement externe")}}else Text("Destination non configurée. Ne payez pas.")}
 if(msg.isNotBlank())Text(msg)
}
